'use strict';
// Simple navigation and reversible upload removal. Existing source data stay intact.
navItems.find(n=>n[0]==='documents')[1]='Unterlagen';
navItems.find(n=>n[0]==='inbox')[1]='Zahlungen';
navItems.find(n=>n[0]==='inbox')[2]='wallet';
navItems.push(['taxyear','Mein Steuerjahr','check']);
navItems.sort((a,b)=>['overview','inbox','documents','tasks','chat','taxyear','calendar','assessments','knowledge','safety','settings','banking','transactions'].indexOf(a[0])-['overview','inbox','documents','tasks','chat','taxyear','calendar','assessments','knowledge','safety','settings','banking','transactions'].indexOf(b[0]));

function paymentTabs(view){return `<nav class="payment-tabs" aria-label="Zahlungsansicht">${[['inbox','Nach Monaten'],['banking','Kontoauszüge']].map(([id,label])=>`<a href="#${id}" data-action="navigate" data-view="${id}"${id===view?' aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function trashMarkup(){const rows=app.uploadTrash||[];return `<details class="home-details upload-trash"><summary>Papierkorb${rows.length?' · '+rows.length:''}</summary><div class="home-details-body"><p class="small muted">Entfernte Uploads bleiben wiederherstellbar. Bereits übernommene Zahlungen bleiben erhalten.</p>${rows.map(r=>`<div class="account-line"><div><strong>${esc(r.label)}</strong><p class="small muted">Entfernt ${stamp(r.created_at)}</p></div>${button('Wiederherstellen','restore-upload','','small',`data-id="${r.id}"`)}</div>`).join('')||'<p class="small muted">Der Papierkorb ist leer.</p>'}</div></details>`;}
function uploadRows(data){
 const pending=app.intakeJobs.filter(j=>j.kind==='pdf'&&!j.import_id);
 const knownDocs=new Set([...app.intakeJobs.map(j=>j.document_id),...data.imports.map(i=>i.statement_document_id)]);
 const unassigned=docsForYear().filter(d=>d.kind==='Kontoauszug'&&!knownDocs.has(d.id));
 const rows=[...unassigned.map(d=>({id:d.id,kind:'document',title:d.title,account:null,date:d.created_at,status:'Noch nicht eingelesen',state:'saved',readable:!!d.stored_name&&/\.pdf$/i.test(d.filename)})),...data.imports.filter(i=>!pending.some(j=>j.document_id===i.statement_document_id)).map(i=>({id:i.id,kind:'import',source_kind:i.source_kind,title:i.filename,account:i.account_id,date:i.created_at,status:i.state==='committed'?'Übernommen':i.state==='partial'?'Teilweise übernommen':'Zahlungen prüfen',state:i.state})),...pending.map(j=>({id:j.id,kind:'job',title:app.data.documents.find(d=>d.id===j.document_id)?.title||'PDF-Auszug',account:j.account_id,date:j.created_at,status:j.progress?.includes('Monate übernommen')?j.progress:{saved:'Bereit zum Lesen',queued:'Wird gelesen …',running:'Wird gelesen …',review:'Ergebnis prüfen',error:'Erneut öffnen'}[j.state]||'Prüfen',state:j.state}))].sort((a,b)=>b.date.localeCompare(a.date));
 return rows.map(r=>`<div class="upload-row"><span class="upload-file-icon">${icon('file')}</span><div class="upload-row-main"><strong>${esc(r.title)}</strong><p class="small muted">${esc(r.kind==='document'?'Konto noch zuordnen':accountName(r.account))} · ${stamp(r.date)}</p><span class="tag ${r.state==='committed'?'green':r.state==='error'?'amber':''}">${r.status}</span></div><div class="actions">${r.state==='committed'&&r.source_kind==='pdf'?button('Prüfverlauf','resume-import','','small',`data-id="${r.id}"`):''}${r.state==='committed'?button('Original','bank-original','file','small',`data-id="${r.id}" data-filename="${esc(r.title)}"`):button(r.kind==='document'&&r.readable?'Einlesen':'Öffnen',r.kind==='job'?'intake-job':r.kind==='document'?(r.readable?'read-statement-document':'open-document'):'resume-import','arrow','small',`data-id="${r.id}"`)}${button('Entfernen','trash-upload','','ghost small',`data-${r.kind==='job'?'job':r.kind==='document'?'document':'import'}-id="${r.id}"`)}</div></div>`).join('');
}
const workspaceRender=render,workspaceAction=action;
render=function(){
 if(!app.data)return;
 if(app.view==='taxyear'){app.view='overview';workspaceRender();app.view='taxyear';$('#main').innerHTML=taxYearView();}
 else workspaceRender();
 const active=app.view==='banking'||app.view==='transactions'?'inbox':app.view;
 document.querySelectorAll('#nav .nav-item').forEach(a=>{const selected=a.dataset.view===active;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#breadcrumb-current').textContent=navItems.find(n=>n[0]===app.view)?.[1]||'Übersicht';
 $('#main').dataset.view=app.view;
 if(['taxyear','calendar','assessments','knowledge','safety','settings'].includes(app.view))$('#nav .nav-more').open=true;
};
function taxYearView(){
 const rows=baseTxForYear(),open=rows.filter(needsEvidence),tasks=tasksForYear().filter(t=>t.status!=='done'),profile=(app.data.tax_profiles||[]).find(p=>p.year===app.year),docs=docsForYear().filter(d=>d.kind!=='Kontoauszug');
 const statusKnown=profile&&profile.vat_status!=='unknown';
 return head('Dein Steuerjahr '+app.year+'.','Ein Schritt nach dem anderen. Deine Ablage ist der Anfang.')+
 `<div class="year-path"><section class="panel year-step"><span class="step-number">1</span><div><h2>Alles sammeln</h2><p>Kontoauszüge, bar bezahlte Einkäufe, Rechnungen und Finanzamtbriefe ablegen.</p><p class="small muted">${rows.length} ${rows.length===1?'Zahlung':'Zahlungen'} · ${docs.length} Unterlagen gespeichert. Ob alles vollständig ist, musst du mit deinen Konten und Unterlagen abgleichen.</p><div class="actions">${button('Zu den Zahlungen','navigate','wallet','small','data-view="inbox"')}${button('Unterlage hinzufügen','new-document','plus','small')}</div><details class="source-details"><summary>Was gehört für mich dazu?</summary><p>Für YouTube und Twitch: Auszahlungen, Abos, Technik, Partnerverträge und kostenlose Produkte. Auch privat bezahlte Anschaffungen für dein Gewerbe erfassen. Für privat: zum Beispiel die Lohnsteuerbescheinigung deines Ferienjobs und weitere relevante Nachweise.</p></details></div></section>
 <section class="panel year-step"><span class="step-number">2</span><div><h2>Offene Punkte klären</h2><p>${open.length?`${open.length} Zahlungen brauchen noch eine Einordnung oder einen Beleg.`:'Bei den erfassten Zahlungen ist keine offene Einordnung oder Beleglücke markiert.'}</p><p class="small muted">${statusKnown?'Umsatzsteuerstatus ist hinterlegt.':'Dein Umsatzsteuerstatus ist noch zu klären.'} Abgabestand: ${{unknown:'noch zu klären',open:'noch offen',submitted:'als abgegeben dokumentiert'}[profile?.filing_status||'unknown']}. ${tasks.length} offene Aufgaben in diesem Jahr. Beleg vorhanden bedeutet noch nicht steuerlich geprüft.</p><div class="actions">${button('Zahlungen prüfen','review-open','check','small')}${button('Steuerstatus','startcheck','settings','small')}${button('Aufgaben & Fristen','navigate','calendar','small','data-view="tasks"')}</div></div></section>
 <section class="panel year-step"><span class="step-number">3</span><div><h2>EÜR vorbereiten</h2><p>Zahlungen steuerlich zuordnen, AfA und Ergänzungen erfassen und den Arbeitsentwurf exportieren.</p><div class="actions">${button('EÜR-Arbeitsbereich','navigate','arrow','primary small','data-view="euer"')}${button('Zahlungsliste als CSV','export','download','small')}${button('Abgaben dokumentieren','navigate','check','small','data-view="tasks"')}</div><details class="source-details" open><summary>Was diese Version noch nicht erledigt</summary><p>Der EÜR-Arbeitsentwurf berechnet bestätigte Positionen für 2025. Weitere Gewinnkorrekturen, Bilanz, Umsatzsteuererklärung und private Einkommensteuererklärung bleiben gesonderte Schritte. Es erfolgt keine ELSTER-Übermittlung. Welche Erklärungen du benötigst, ist anhand deines Steuerstatus zu klären.</p></details></div></section></div>`;
}
// One overview: business amounts, three entry points, and the next open work.
overviewView=function(){
 const tasks=app.data.tasks.filter(t=>t.status!=='done').sort((a,b)=>nextTaskDate(a).localeCompare(nextTaskDate(b))||a.title.localeCompare(b.title));
 const all=baseTxForYear(),sum=totals(txForYear()),open=all.filter(needsEvidence).length,storage=app.data.storage||{};
 const recent=[...all].sort((a,b)=>b.paid_on.localeCompare(a.paid_on)).slice(0,3);
 return `<div class="home-calm studio-home">${head('Dein Überblick.','YouTube, Twitch und privat. Alles an seinem Platz.',button('Mein Steuerjahr','navigate','arrow','ghost small','data-view="taxyear"'))}
 ${storage.backup?.error?`<div class="home-alert" role="alert"><div><strong>Sicherung prüfen</strong><p>${esc(storage.backup.error)}</p></div>${button('Öffnen','navigate','','small','data-view="safety"')}</div>`:''}
 <section class="panel year-overview" aria-label="Erfasste betriebliche Zahlungen"><div class="year-overview-title"><span>Betriebliche Zahlungen</span><span class="year-label">${app.year}</span></div><div class="year-metrics"><div><span class="metric-label"><i class="metric-dot income-dot"></i>Einnahmen</span><strong>${money(sum.income)}</strong></div><div><span class="metric-label"><i class="metric-dot expense-dot"></i>Ausgaben</span><strong>${money(sum.expense)}</strong></div><button data-action="review-open" class="metric-open"><span class="metric-label">Zahlungen prüfen ${icon('arrow')}</span><strong>${open}<span>offen</span></strong></button></div><p class="year-caption">Nur als betrieblich eingeordnete Zahlungen · keine fertige EÜR.</p></section>
 <div class="home-work-grid"><section class="panel capture-panel"><div class="panel-header"><div><h2>Was möchtest du erledigen?</h2><span class="small muted">Deine Unterlagen werden lokal gespeichert.</span></div></div><div class="capture-actions"><button class="home-action home-action-primary" data-action="bank-import"><span class="action-symbol">${icon('upload')}</span><span><strong>Auszug hochladen</strong><small>CSV oder PDF · nach Monaten prüfen</small></span>${icon('arrow')}</button><div class="capture-secondary"><button class="home-action" data-action="new-transaction"><span class="action-symbol">${icon('plus')}</span><span><strong>Zahlung eintragen</strong><small>Auch bar bezahlt</small></span></button><button class="home-action" data-action="new-document"><span class="action-symbol">${icon('file')}</span><span><strong>Unterlage ablegen</strong><small>Rechnung, Brief oder Vertrag</small></span></button></div></div></section>
 <section class="panel home-next"><div class="panel-header"><h2>Als Nächstes</h2><span class="tag">${tasks.length} offen</span></div><div class="panel-body">${tasks.length?tasks.slice(0,2).map(t=>`<div class="home-task">${taskRow(t)}<span class="home-task-year">Arbeitsjahr ${t.year}</span></div>`).join(''):`<div class="next-empty"><span class="next-symbol">${icon('check')}</span><strong>Keine offenen Aufgaben erfasst</strong><p>Deinen nächsten Schritt findest du im Jahresleitfaden.</p>${button('Mein Steuerjahr öffnen','navigate','arrow','ghost small','data-view="taxyear"')}</div>`}</div>${tasks.length?`<div class="quiet-panel-footer">${button('Aufgaben '+app.year,'navigate','arrow','ghost small','data-view="tasks"')}</div>`:''}</section></div>
 ${draftBanner()}
 <section class="panel home-recent"><div class="panel-header"><h2>Zuletzt erfasst</h2>${button('Alle Zahlungen','navigate','arrow','ghost small','data-view="inbox"')}</div>${recent.length?`<div class="recent-payments">${recent.map(t=>`<button class="recent-payment" data-action="evidence" data-id="${t.id}"><span class="recent-symbol">${icon(t.payment_method==='cash'?'wallet':'file')}</span><span class="recent-description"><strong>${esc(t.partner)}</strong><small>${fmtDate(t.paid_on)} · ${esc(scopeNames[t.scope]||'Ungeklärt')}</small></span><span class="recent-amount">${t.direction==='income'?'+':'−'} ${money(t.amount_cents)}</span>${icon('right')}</button>`).join('')}</div>`:`<div class="recent-empty"><span>${icon('wallet')}</span><p>Hier erscheinen deine gespeicherten und freigegebenen Zahlungen.</p></div>`}</section></div>`;
};
async function removalDialog(target){
 if($('#pdf-review-form'))await queuePdfSave($('#pdf-review-form'));
 await app.reviewQueue;
 const p=await api('/api/trash/preview',target);app.removal={...target,token:p.token};
 showModal('Upload entfernen?',`<div class="modal-body"><p><strong>${esc(p.label)}</strong></p><p class="section-gap">Der Upload verschwindet aus der normalen Ansicht. Im Papierkorb kannst du ihn wiederherstellen.</p><p class="removal-effect">${p.payments?`${p.payments} bereits ${p.payments===1?'übernommene Zahlung bleibt':'übernommene Zahlungen bleiben'} erhalten. Beträge und Auswertungen ändern sich dadurch nicht.`:'Aus diesem Upload sind keine aktiven Zahlungen verknüpft.'}</p>${p.jobs.some(j=>['running','queued'].includes(j.state))?'<p class="small muted">Die laufende Auswertung wird beendet. Ergebnisse einer noch laufenden KI-Anfrage werden verworfen.</p>':''}<p class="small muted">Originaldateien werden nicht endgültig gelöscht.</p><div class="form-result" role="alert"></div></div><div class="modal-footer">${button('Abbrechen','close-modal','','ghost')}${button('In Papierkorb','confirm-remove','','primary')}</div>`);
}
action=async function(name,el){
 if(name==='read-statement-document'){const d=app.data.documents.find(d=>d.id===el.dataset.id);const response=await fetch('/api/documents/'+d.id+'/file');if(!response.ok)throw new Error('Original konnte nicht geöffnet werden.');return bankImportForm(null,new File([await response.blob()],d.filename,{type:'application/pdf'}));}

 if(name==='archive'&&el.dataset.entity==='documents')return removalDialog({document_id:el.dataset.id});
 if(name==='trash-upload')return removalDialog(el.dataset.documentId?{document_id:el.dataset.documentId}:el.dataset.importId?{import_id:el.dataset.importId}:{job_id:el.dataset.jobId});
 if(name==='confirm-remove'){
  el.disabled=true;try{const result=await api('/api/trash/remove',app.removal);clearTimeout(app.intakePoll);app.suppressDraft=true;closeModal();app.suppressDraft=false;app.bankYear=null;await refresh();await loadBank();toast(result.payments_preserved?'Upload entfernt. Übernommene Zahlungen bleiben erhalten.':'Im Papierkorb · wiederherstellbar.');}catch(e){const f=$('#modal .form-result');if(f){f.className='form-result form-error';f.textContent=e.message;}else toast(e.message,true);}finally{el.disabled=false;}return;
 }
 if(name==='restore-upload'){await api('/api/trash/restore',{id:el.dataset.id});app.bankYear=null;await refresh();await loadBank();if($('#trash-dialog'))$('#trash-dialog').innerHTML=trashMarkup();toast('Upload wiederhergestellt.');return;}
 if(name==='open-trash'){await loadBank();showModal('Papierkorb · '+app.year,`<div class="modal-body" id="trash-dialog">${trashMarkup()}</div>`);$('#trash-dialog details').open=true;return;}
 if(name==='review-open'){app.inboxFilter='open';app.inboxMonth='';return navigate('inbox');}
 if(name==='show-transactions')return navigate('inbox');
 return workspaceAction(name,el);
};
